fn encode_shift(s: Vec<char>) -> Vec<char> {
    s.into_iter()
     .map(|c| {
         // Convert the character to its ASCII byte value
         let b = c as u8;
         // Shift by 5 with wrap-around in the range 'a'..='z'
         let shifted = (b - b'a' + 5) % 26 + b'a';
         // Convert back to a char
         shifted as char
     })
     .collect()
}

